// Copied from transcribe/th16/touhou-bullets.ecl (TH16 v1.00a type 0..43 slots).
// Only the two types this card fires are kept.
const TH16_RICE: int = 480; // source etSprite type 8, color 6
const TH16_BALL: int = 416; // source etSprite type 4, color 2

// TH16 v1.00a st04.ecl.txt MainSub00:1388-1426 — GirlA01 formation wave.
// Source dependencies: GirlA01 335-343, GirlA01F 345-367, GirlA01_at 369-412,
// GirlA01_at2 414-451. GirlA01_color/anmAlpha/dropSeason are presentation/reward and are
// omitted by the shared policy; every firing, box and movement value below is source.
// Source MainSub00_1112 loops $B=2 times: 14 enmCreate/enmCreateM pairs, 20 frames apart.

const TIME_LIMIT: int = 1224;
const OPENING_BUFFER: int = 120;

// GirlA01_at (369-412): emitter 0, fixed down volley every 5 frames, 40 groups of 5,
// 30-frame gap between groups. Difficulty only changes layer count and speed.
async sub girl_at() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1.5fx; // !E
    var s1: fx = 0fx;
    if rank == 1 { s0 = 2fx; }                 // !N
    if rank >= 2 { layers = 2; s0 = 3.5fx; s1 = 2.2fx; } // !H / !LO
    wait(60);
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 6);
    sh_ring(0, 0);
    sh_aim(0, 0);                 // etAim mode1: fixed direction
    sh_count(0, 1, 1);
    sh_angle(0, 90deg, 0deg);     // etAngle base 1.5707964f
    sh_speed(0, s0, 0fx);
    sh_dist(0, -(4fx * s0));      // etEx type2 ANIM a=1: position -= 4*velocity
    if layers == 2 {
        sh_reset(1);
        sh_sprite(1, TH16_RICE, 6);
        sh_ring(1, 0);
        sh_aim(1, 0);
        sh_count(1, 1, 1);
        sh_angle(1, 90deg, 0deg);
        sh_speed(1, s1, 0fx);
        sh_dist(1, -(4fx * s1));
    }
    for group in 0..40 {
        for k in 0..5 {
            sh_fire(0);
            if layers == 2 { sh_fire(1); }
            wait(5);
        }
        wait(30);
    }
}

// GirlA01_at2 (414-451): emitter 1, player-aimed ball every 60 frames, 40 times.
// thecl mask !NHL: absent on Easy.
async sub girl_at2() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 2.2fx; // !N
    var s1: fx = 2.2fx;
    if rank == 2 { s0 = 3fx; }                                  // !H
    if rank == 3 { layers = 2; s0 = 3.5fx; s1 = 2.2fx; }        // !LO(2 layers)
    wait(160);
    sh_reset(2);
    sh_sprite(2, TH16_BALL, 2);
    sh_ring(2, 0);
    sh_aim(2, 1);                 // etAim mode0: aimed fan
    sh_count(2, 1, 1);
    sh_angle(2, 0deg, 0deg);      // etAngle base 0, offset 0
    sh_speed(2, s0, 0fx);
    sh_dist(2, -(4fx * s0));
    if layers == 2 {
        sh_reset(3);
        sh_sprite(3, TH16_BALL, 2);
        sh_ring(3, 0);
        sh_aim(3, 1);
        sh_count(3, 1, 1);
        sh_angle(3, 0deg, 0deg);
        sh_speed(3, s1, 0fx);
        sh_dist(3, -(4fx * s1));
    }
    for i in 0..40 {
        sh_fire(2);
        if layers == 2 { sh_fire(3); }
        wait(60);
    }
}

// GirlA01 -> GirlA01F (335-367). M-created enemies carry the native mirror bit, which flips
// the moveVel angle (404/405 are the mirrored path, 428-431 are the NM path); firing angles
// are not mirrored. Bodies/boxes per enemy-state.md: ordinary circle takes width*0.5.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);            // setHurtbox(24,24)
    set_hitbox(8fx);              // setHitbox(16,16)
    spawn girl_at();
    if global(GVAR_RANK) != 0 { spawn girl_at2(); } // !NHL
    var a2: angle = 45deg;        // 0.7853982f
    var a3: angle = 0deg;
    if mirror != 0 {
        a2 = 135deg;
        a3 = 180deg;
    }
    move_vel(0, 90deg, 0.5fx, EASE_LINEAR);      // moveVel(pi/2, 0.5)
    wait(60);
    move_vel(60, a2, 1.5fx, EASE_LINEAR);        // +60: moveVelTime(60,0,pi/4,1.5)
    wait(60);
    move_vel(60, a3, 2.5fx, EASE_LINEAR);        // +60: moveVelTime(60,0,0,2.5)
    wait(60);
    loop { wait(1); }            // GirlA01F keep-alive loop; engine recycles offscreen
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wait(60);                    // MainSub00:1392 wait(60) before the first enmCreate
    for round in 0..2 {
        // left column enmCreate, right column enmCreateM (mirrored), 20 frames apart
        _ = spawn_enemy(-128fx, 64fx, 200, 0, 0, 0, girl(0)); wait(20);
        _ = spawn_enemy(128fx, 64fx, 200, 0, 0, 0, girl(1)); wait(20);
        _ = spawn_enemy(-32fx, 80fx, 200, 0, 0, 0, girl(0)); wait(20);
        _ = spawn_enemy(32fx, 80fx, 200, 0, 0, 0, girl(1)); wait(20);
        _ = spawn_enemy(-64fx, 90fx, 200, 0, 0, 0, girl(0)); wait(20);
        _ = spawn_enemy(64fx, 90fx, 200, 0, 0, 0, girl(1)); wait(20);
        _ = spawn_enemy(-192fx, 64fx, 200, 0, 0, 0, girl(0)); wait(20);
        _ = spawn_enemy(192fx, 64fx, 200, 0, 0, 0, girl(1)); wait(20);
        _ = spawn_enemy(-160fx, 80fx, 200, 0, 0, 0, girl(0)); wait(20);
        _ = spawn_enemy(160fx, 80fx, 200, 0, 0, 0, girl(1)); wait(20);
        _ = spawn_enemy(-128fx, 90fx, 200, 0, 0, 0, girl(0)); wait(20);
        _ = spawn_enemy(128fx, 90fx, 200, 0, 0, 0, girl(1)); wait(20);
        _ = spawn_enemy(-32fx, 30fx, 200, 0, 0, 0, girl(0)); wait(20);
        _ = spawn_enemy(32fx, 30fx, 200, 0, 0, 0, girl(1)); wait(20);
    }
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
